// ========== وظائف مساعدة للسعر ==========

export const formatPrice = (priceUSD: number): string => {
  if (priceUSD === 0) {
    return "قابل للتفاوض";
  }
  return `$${priceUSD.toLocaleString()}`;
};

export const isNegotiablePrice = (priceUSD: number): boolean => {
  return priceUSD === 0;
};

export const getModelsByPriceType = (
  type: "fixed" | "negotiable",
): VehicleModel[] => {
  if (type === "negotiable") {
    return vehicleModels.filter((model) => model.priceUSD === 0);
  }
  // نظرًا لأن جميع الأسعار قابلة للتفاوض الآن، قم بإرجاع مصفوفة فارغة للأسعار الثابتة
  return [];
};

// وظيفة مساعدة للحصول على الطرازات ذات الأسعار القابلة للتفاوض (جميع الطرازات الآن)
export const getNegotiableModels = (): VehicleModel[] => {
  return vehicleModels.filter((model) => model.priceUSD === 0);
};

// وظيفة مساعدة للحصول على الطرازات المميزة (للعرض على الصفحة الرئيسية)
export const getFeaturedModels = (limit?: number): VehicleModel[] => {
  const featured = vehicleModels.filter((model) => model.featured);
  return limit ? featured.slice(0, limit) : featured;
};

// وظيفة مساعدة للحصول على الطرازات حسب الحالة
export const getModelsByStatus = (
  status: VehicleModel["status"],
): VehicleModel[] => {
  return vehicleModels.filter((model) => model.status === status);
};

// وظيفة مساعدة للحصول على الطرازات حسب العلامة التجارية
export const getModelsByBrand = (brand: string): VehicleModel[] => {
  return vehicleModels.filter(
    (model) => model.brand.toLowerCase() === brand.toLowerCase(),
  );
};

// وظيفة مساعدة للحصول على الطرازات حسب الفئة
export const getModelsByCategory = (category: string): VehicleModel[] => {
  if (category === "all") return vehicleModels;
  if (category === "commercial") {
    return vehicleModels.filter(
      (model) => model.category === "Commercial" || model.category === "Pickup",
    );
  }
  return vehicleModels.filter(
    (model) => model.category.toLowerCase() === category.toLowerCase(),
  );
};

// وظيفة مساعدة محدثة للحصول على الطرازات حسب النطاق السعري (جميعها قابلة للتفاوض الآن)
export const getModelsByPriceRange = (
  min: number,
  max: number,
): VehicleModel[] => {
  // نظرًا لأن جميع الأسعار قابلة للتفاوض، قم بإرجاع مصفوفة فارغة لنطاقات الأسعار الثابتة
  return [];
};

// وظيفة مساعدة للحصول على الطرازات حسب نوع الوقود
export const getModelsByFuelType = (fuelType: string): VehicleModel[] => {
  if (fuelType === "all") return vehicleModels;
  return vehicleModels.filter(
    (model) => model.specs.fuelType.toLowerCase() === fuelType.toLowerCase(),
  );
};

// وظيفة مساعدة للحصول على أحدث الطرازات
export const getNewestModels = (limit: number = 6): VehicleModel[] => {
  return [...vehicleModels].sort((a, b) => b.year - a.year).slice(0, limit);
};

// وظيفة مساعدة محدثة للحصول على أفضل الطرازات قيمة (جميعها قابلة للتفاوض الآن)
export const getBestValueModels = (limit: number = 4): VehicleModel[] => {
  // قم بإرجاع الطرازات المميزة أو ذات التقييم العالي
  return vehicleModels
    .filter((model) => model.rating && model.rating >= 4.0)
    .sort((a, b) => (b.rating || 0) - (a.rating || 0))
    .slice(0, limit);
};

// وظيفة مساعدة محدثة للحصول على الطرازات الفاخرة (جميعها قابلة للتفاوض الآن)
export const getPremiumModels = (limit: number = 4): VehicleModel[] => {
  // قم بإرجاع الطرازات ذات الحالة الفاخرة أو التقييمات العالية
  return vehicleModels
    .filter(
      (model) =>
        model.status === "Limited Edition" ||
        (model.rating && model.rating >= 4.7),
    )
    .slice(0, limit);
};

// وظيفة مساعدة للحصول على الطرازات ذات الخصومات
export const getDiscountedModels = (): VehicleModel[] => {
  return vehicleModels.filter((model) => model.discount && model.discount > 0);
};

// وظيفة مساعدة للبحث في الطرازات
export const searchModels = (query: string): VehicleModel[] => {
  const searchTerm = query.toLowerCase();
  return vehicleModels.filter(
    (model) =>
      model.brand.toLowerCase().includes(searchTerm) ||
      model.model.toLowerCase().includes(searchTerm) ||
      model.description.toLowerCase().includes(searchTerm) ||
      model.category.toLowerCase().includes(searchTerm) ||
      model.tagline?.toLowerCase().includes(searchTerm),
  );
};

// وظيفة مساعدة للحصول على العلامات التجارية الفريدة مع الأعداد
export const getBrandsWithCounts = () => {
  const brandMap = new Map();
  vehicleModels.forEach((model) => {
    const count = brandMap.get(model.brand) || 0;
    brandMap.set(model.brand, count + 1);
  });

  return Array.from(brandMap.entries()).map(([brand, count]) => ({
    brand,
    count,
    logo: `/images/brands/${brand.toLowerCase().replace(/\s+/g, "-")}.png`,
  }));
};

// وظيفة مساعدة للحصول على الطراز بواسطة المعرف
export const getModelById = (id: string): VehicleModel | undefined => {
  return vehicleModels.find((model) => model.id === id);
};

// وظيفة مساعدة للحصول على طرازات مماثلة (حسب الفئة أو العلامة التجارية)
export const getSimilarModels = (
  currentModel: VehicleModel,
  limit: number = 4,
): VehicleModel[] => {
  return vehicleModels
    .filter(
      (model) =>
        model.id !== currentModel.id &&
        (model.category === currentModel.category ||
          model.brand === currentModel.brand),
    )
    .slice(0, limit);
};

// وظيفة مساعدة محدثة للحصول على الطرازات مرتبة حسب السعر (جميعها قابلة للتفاوض الآن)
export const getModelsSortedByPrice = (
  order: "asc" | "desc" = "asc",
): VehicleModel[] => {
  // نظرًا لأن جميع الأسعار 0، قم بالترتيب حسب معايير أخرى مثل السنة أو التقييم
  return [...vehicleModels].sort((a, b) => b.year - a.year);
};

// وظيفة مساعدة للحصول على الطرازات مرتبة حسب التقييم
export const getModelsSortedByRating = (): VehicleModel[] => {
  return [...vehicleModels].sort((a, b) => (b.rating || 0) - (a.rating || 0));
};

// وظيفة مساعدة للحصول على الطرازات الكهربائية ذات المدى > 500 كم
export const getLongRangeEVs = (): VehicleModel[] => {
  return vehicleModels.filter(
    (model) =>
      model.specs.fuelType === "Electric" &&
      model.specs.range &&
      parseInt(model.specs.range.split(" ")[0]) > 500,
  );
};

// وظيفة مساعدة للحصول على الطرازات العائلية (7 مقاعد)
export const getFamilyModels = (): VehicleModel[] => {
  return vehicleModels.filter((model) => model.specs.seats >= 7);
};

// وظيفة مساعدة للحصول على الطرازات الرياضية (تسارع < 6 ثوانٍ)
export const getSportModels = (): VehicleModel[] => {
  return vehicleModels.filter(
    (model) =>
      model.specs.acceleration &&
      parseFloat(model.specs.acceleration.split("s")[0]) < 6,
  );
};

// وظيفة مساعدة للحصول على أفضل الطرازات مبيعًا
export const getBestSellingModels = (): VehicleModel[] => {
  return vehicleModels.filter((model) => model.status === "Best Seller");
};

// وظيفة مساعدة للحصول على الطرازات القادمة قريبًا
export const getComingSoonModels = (): VehicleModel[] => {
  return vehicleModels.filter((model) => model.status === "Coming Soon");
};

// وظيفة مساعدة للحصول على الطرازات محدودة الإصدار
export const getLimitedEditionModels = (): VehicleModel[] => {
  return vehicleModels.filter((model) => model.status === "Limited Edition");
};

// وظائف الإحصائيات
export const getTotalModelsCount = (): number => vehicleModels.length;

export const getAveragePrice = (): number => {
  // نظرًا لأن جميع الأسعار قابلة للتفاوض، قم بإرجاع 0
  return 0;
};

export const getAvailableModelsCount = (): number => {
  return vehicleModels.filter((model) => model.available).length;
};

export const getEVCount = (): number => {
  return vehicleModels.filter((model) => model.specs.fuelType === "Electric")
    .length;
};

export const getHybridCount = (): number => {
  return vehicleModels.filter(
    (model) =>
      model.specs.fuelType === "Hybrid" || model.specs.fuelType === "PHEV",
  ).length;
};

export const getNegotiableCount = (): number => {
  return vehicleModels.filter((model) => model.priceUSD === 0).length;
};

